import React from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, Share2, Bookmark } from 'lucide-react';
import './BlogPost.css';

function BlogPost({ posts }) {
  const { id } = useParams();
  const navigate = useNavigate();
  const post = posts.find((p) => p.id === parseInt(id));

  if (!post) {
    return (
      <div className="blog-post-container">
        <div className="post-not-found">
          <h2>Post not found</h2>
          <Link to="/" className="back-link">
            <ArrowLeft size={18} />
            Back to articles
          </Link>
        </div>
      </div>
    );
  }

  const relatedPosts = posts.filter(
    (p) => p.category === post.category && p.id !== post.id
  );

  return (
    <article className="blog-post">
      <button className="post-back-btn" onClick={() => navigate('/')}>
        <ArrowLeft size={20} />
      </button>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
        className="post-hero"
      >
        <img src={post.image} alt={post.title} className="post-hero-image" />
      </motion.div>

      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, delay: 0.2 }}
        className="post-container"
      >
        <div className="post-header">
          <div className="post-meta-top">
            <span className="post-category">{post.category}</span>
            <span className="post-reading-time">{post.readingTime} min read</span>
          </div>

          <h1 className="post-title">{post.title}</h1>

          <div className="post-author-section">
            <div className="author-details">
              <div className="author-avatar">{post.author.charAt(0)}</div>
              <div>
                <div className="author-name">{post.author}</div>
                <div className="post-date">{post.date}</div>
              </div>
            </div>
            <div className="post-actions">
              <button className="action-btn" title="Share">
                <Share2 size={18} />
              </button>
              <button className="action-btn" title="Save">
                <Bookmark size={18} />
              </button>
            </div>
          </div>
        </div>

        <div className="post-body">
          {post.content.split('\n\n').map((paragraph, index) => {
            if (paragraph.startsWith('##')) {
              return (
                <h2 key={index} className="post-h2">
                  {paragraph.replace('##', '').trim()}
                </h2>
              );
            }
            if (paragraph.startsWith('###')) {
              return (
                <h3 key={index} className="post-h3">
                  {paragraph.replace('###', '').trim()}
                </h3>
              );
            }
            if (paragraph.startsWith('-')) {
              return (
                <ul key={index} className="post-list">
                  {paragraph
                    .split('\n')
                    .filter((line) => line.startsWith('-'))
                    .map((line, i) => (
                      <li key={i}>{line.replace('- ', '').trim()}</li>
                    ))}
                </ul>
              );
            }
            if (paragraph.startsWith('```')) {
              const code = paragraph.replace(/```javascript\n/g, '').replace(/```/g, '');
              return (
                <pre key={index} className="post-code">
                  <code>{code}</code>
                </pre>
              );
            }
            return (
              <p key={index} className="post-paragraph">
                {paragraph}
              </p>
            );
          })}
        </div>

        <div className="post-footer">
          <div className="post-tags">
            {post.tags.map((tag) => (
              <span key={tag} className="post-tag">
                #{tag}
              </span>
            ))}
          </div>

          {relatedPosts.length > 0 && (
            <div className="related-posts">
              <h3>More from {post.category}</h3>
              <div className="related-posts-grid">
                {relatedPosts.slice(0, 2).map((relatedPost) => (
                  <Link
                    key={relatedPost.id}
                    to={`/post/${relatedPost.id}`}
                    className="related-post-card"
                  >
                    <h4>{relatedPost.title}</h4>
                    <p>{relatedPost.readingTime} min read</p>
                  </Link>
                ))}
              </div>
            </div>
          )}
        </div>
      </motion.div>
    </article>
  );
}

export default BlogPost;
